import os
from google import genai

def get_vertex_ai_client(project_id: str, location: str):
    # Ensure GOOGLE_APPLICATION_CREDENTIALS environment variable is set
    # or that gcloud default credentials are configured.
    return genai.Client(vertexai=True, project=project_id, location=location)

from google import genai
from model_models import ModelInvocationPayload, ModelConfig
from model_client import get_vertex_ai_client
from typing import Iterator, Dict, Any

def stream_platform_generation(
    payload: ModelInvocationPayload, config: ModelConfig
) -> Iterator[Dict[str, Any]]:
    client = get_vertex_ai_client(config.project_id, config.location)
    model = client.get_model(config.model_id)

    # Use the generate_content method with stream=True for streaming responses
    response_stream = model.generate_content(
        payload.text, stream=True
    )

    for chunk in response_stream:
        yield {
            "text_chunk": chunk.text,
            "finish_reason": chunk.finish_reason.name if chunk.finish_reason else None,
            "metadata": {"prompt_token_count": chunk.usage_metadata.prompt_token_count if chunk.usage_metadata else 0, # Placeholder, actual streaming metadata may vary
                         "candidates_token_count": chunk.usage_metadata.candidates_token_count if chunk.usage_metadata else 0}
        }

from google import genai
from model_models import ModelInvocationPayload, ModelConfig, SafetyCheckResponse
from model_client import get_vertex_ai_client
from typing import List

def check_platform_output_safety(
    payload: ModelInvocationPayload, config: ModelConfig
) -> SafetyCheckResponse:
    client = get_vertex_ai_client(config.project_id, config.location)
    model = client.get_model(config.model_id)

    # Note: For safety attributes, often the input is also checked. 
    # Here we are focusing on output safety check after generation.
    response = model.generate_content(
        payload.text
    )

    is_safe = True
    reasons: List[str] = []

    if response.candidates:
        for candidate in response.candidates:
            if candidate.safety_ratings:
                for rating in candidate.safety_ratings:
                    # Assuming Block_NONE means safe, anything else means potentially unsafe
                    if rating.blocked: # or rating.probability > 0.5 for example to set a threshold
                        is_safe = False
                        reasons.append(f"Category: {rating.category.name}, Blocked: {rating.blocked}, Probability: {rating.probability.name}")
            # Also check finish_reason for SAFETY as a blocking reason
            if candidate.finish_reason and candidate.finish_reason.name == "SAFETY":
                is_safe = False
                reasons.append(f"Generation stopped due to safety concerns.")

    return SafetyCheckResponse(is_safe=is_safe, reasons=reasons)

from google.cloud import translate_v3 as translate
from model_models import ModelConfig, LocalizedOutput

def translate_platform_output(
    text: str, target_language_code: str, config: ModelConfig
) -> LocalizedOutput:
    client = translate.TranslationServiceClient()

    parent = f"projects/{config.project_id}/locations/{config.location}"

    response = client.translate_text(
        request={
            "parent": parent,
            "contents": [text],
            "target_language_code": target_language_code,
        }
    )

    translated_text = ""
    if response.translations:
        translated_text = response.translations[0].translated_text

    return LocalizedOutput(
        language_code=target_language_code,
        translated_text=translated_text
    )
